onChange.script:

if self.custom.session is None: return
if not self.custom.session.has_key('dateRange'): return

dateParams = self.custom.session.dateRange

if dateParams['startDate'] is None and dateParams['endDate'] is None: self.getChild("root").setRange(dateParams['selectedRange'], dateParams['startDate'], dateParams['endDate'])
else: self.params.dates = {'startDate': dateParams['startDate'], 'endDate': dateParams['endDate'], 'selectedRange': dateParams['selectedRange']}

return

transforms.code:

#	system.perspective.print("timer timeNow")

	lastUpdated = self.custom.timer.timeNow
	if not self.custom.timer.enabled: return system.date.now() #		system.perspective.print("timer disabled")
	if lastUpdated is None: return system.date.now() #		system.perspective.print("lastUpdated is None")
#	system.perspective.print("Checking time between %s %s %s %s"%(lastUpdated, value, self.custom.timer.intervalMin, system.date.minutesBetween(lastUpdated, value)))
	if system.date.minutesBetween(lastUpdated, value) < self.custom.timer.intervalMin: return lastUpdated #		system.perspective.print("Not time yet %s"%value)

#	system.perspective.print("Calling setRange() called with %s %s %s" %(self.custom.session.dateRange.selectedRange, None, None))
	self.getChild("root").setRange(self.custom.session.dateRange.selectedRange, None, None)

	return system.date.now()
